+package types
+
+import "strings"
+
+// stringConcatenator concatenates strings. When the left operand is the result
+// of its previous concatenation it appends to that result in place, so folding a
+// left-nested chain of string additions takes time and memory linear in the
+// length of the final string. Every returned string stays valid and unchanged.
+type stringConcatenator struct {
+	buf strings.Builder
+}
+
+func (c *stringConcatenator) concat(lhs, rhs string) string {
+	if lhs != c.buf.String() {
+		c.buf.Reset()
+		c.buf.WriteString(lhs)
+	}
+	c.buf.WriteString(rhs)
+	return c.buf.String()
+}
