+// resolverStringConcatenator returns the concatenator owned by t, or by the
+// enclosing resolver for a loop resolver.
+func resolverStringConcatenator(t typeResolver) *stringConcatenator {
+	switch resolver := t.(type) {
+	case *packageTypeResolver:
+		return &resolver.stringConcat
+	case *functionTypeResolver:
+		return &resolver.stringConcat
+	case *loopTypeResolver:
+		return resolverStringConcatenator(resolver.parentResolver)
+	default:
+		// Unreachable: these are the only resolver kinds. A fresh concatenator is still correct.
+		t.internalError(fmt.Sprintf("no string concatenator for resolver %T", t), diagnostics.Location{})
+		return &stringConcatenator{}
+	}
